mapper.select:
SELECT /* isry.itgcm.dashboard.mapper.MainDashboardMapper.selectCaseCnt */ CASE_PRGRS_STTS_SE_CD , COUNT(1) AS CASE_CNT , TO_CHAR(SYSDATE, 'YYYY-MM-DD HH:MI:SS') AS MODY_DATE FROM SEB100 T1 , SEA200 T2 , SCA100 X , SEB150 Y , SAA000 Z WHERE 1=1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND Z.INST_NO = Y.PIC_INST_NO AND X.ENFSN_NO = Y.CASE_PIC_NO AND Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T1.CASE_PRGRS_STTS_SE_CD IN ('01', '02', '03', '12', '06', '08') -- 등록, 계획, 실행, 종결, 사후관리, 사례종결 /* 등록일자 조회 */ AND T1.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND T1.FRST_REG_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/ GROUP BY CASE_PRGRS_STTS_SE_CD

mapper.insert:
        MERGE INTO DCA010 A
	    USING DUAL
	        ON 
	        (
	            A.ENFSN_NO = #{ENFSN_NO}
	            AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
	        )
	    WHEN MATCHED THEN
	        UPDATE SET
	              A.REG_NOCS = #{CASE_REG_NOCS}
	            , A.PLAN_NOCS = #{CASE_PLAN_NOCS}
	            , A.EXCN_NOCS = #{CASE_EXCN_NOCS}
	            , A.TRMN_APLY_NOCS = #{CASE_TRMN_APLY_NOCS}
	            , A.AFTFCT_MNG_NOCS = #{CASE_AFTFCT_MNG_NOCS}
	            , A.TRMN_NOCS = #{TRMN_NOCS}
	            , LAST_MDFR_ID = #{USER_ID}
	            , LAST_MDFCN_DT = SYSDATE

	    WHEN NOT MATCHED THEN
	        INSERT (
	              ENFSN_NO
	            , UNT_TASKWK_SE_CD
	            , REG_NOCS
	            , PLAN_NOCS
	            , EXCN_NOCS
	            , TRMN_APLY_NOCS
	            , AFTFCT_MNG_NOCS
	            , TRMN_NOCS
	            , FRST_RGTR_ID
	            , FRST_REG_DT
	            , LAST_MDFR_ID
	            , LAST_MDFCN_DT
	        ) VALUES (
	              #{ENFSN_NO}
	            , #{UNT_TASKWK_SE_CD}
	            , #{CASE_REG_NOCS}
	            , #{CASE_PLAN_NOCS}
	            , #{CASE_EXCN_NOCS}
	            , #{CASE_TRMN_APLY_NOCS}
	            , #{CASE_AFTFCT_MNG_NOCS}
	            , #{TRMN_NOCS}
	            , #{USER_ID}
	            , SYSDATE
	            , #{USER_ID}
	            , SYSDATE
	        )

mapper.select:
/*isry.itgcm.linkmng.outsd.mapper.LinkTrprRqstMapper.selectLinkCnt(연계접수목록)*/ SELECT A.LINK_TYPE_SE_CD , COUNT(1) AS LINK_CNT FROM ( SELECT A.SRVC_PVSN_RQST_NO , A.RESRCE_NO , A.HPE_SRVC_YN , A.RQST_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RQST_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RQST_UNT_TASKWK_SE_CD ) AS RQST_UNT_TASKWK_SE_NM , A.RCPT_RQST_COURS_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_RQST_COURS_SE_CD ) AS RCPT_RQST_COURS_SE_NM , A.RQST_YMD , A.CLINT_NO , (SELECT FLNM_ENCPT FROM SCA100 C WHERE C.ENFSN_NO = A.CLINT_NO) AS CLINT_NM , A.RQST_CS_CN , A.PRNMNT_USE_BGNG_YMD , A.PRNMNT_USE_BGNG_HR , A.PRNMNT_USE_END_YMD , A.PRNMNT_USE_END_HR , A.RCPT_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_UNT_TASKWK_SE_CD ) AS RCPT_UNT_TASKWK_SE_NM , A.CLR_NO , (SELECT FLNM_ENCPT FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_NM , A.RCPT_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RCPT_INST_NO = C.INST_NO) AS RCPT_INST_NM , A.RQST_TRPR_INFO_NO , (SELECT D.TRPR_NM_ENCPT FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS RQST_TRPR_INFO_NM , (SELECT D.INDV_IDNTFC_NO FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS INDV_IDNTFC_NO , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.RQST_APLY_YN , A.RQST_DTL_CN , A.LINK_TYPE_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'LINK_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = A.LINK_TYPE_SE_CD ) AS LINK_TYPE_SE_NM , A.ATFINO , A.TRMN_PRCS_YN , A.RQST_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RQST_INST_NO = C.INST_NO) AS RQST_INST_NM FROM SEB400 A ) A, SEB420 B WHERE 1 = 1 AND A. SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND B.RCPT_SN = (CASE WHEN B.RCPT_SE_CD = '40' THEN (SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}) ELSE ((SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO) )END) /* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND (B.RCPT_UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.RRQST_RCPT_UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD})
AND A.LINK_TYPE_SE_CD LIKE '%' || #{LINK_TYPE_CD} || '%'
AND A.LINK_TYPE_SE_CD IN ( SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'LINK_TYPE_SE_CD' AND ADDTNG_MNG_VALUE4 = 'N' )
AND B.RCPT_SE_CD LIKE '%' || #{RCPT_SE_CD} || '%'
AND A.RQST_YMD BETWEEN #{PRNMNT_USE_BGNG_YMD} AND #{PRNMNT_USE_END_YMD}
GROUP BY A.LINK_TYPE_SE_CD

SELECT DISTINCT COUNT(DISTINCT T1.SRV_CNSRQ_ID) OVER() AS TOT_CNT , T1.SRV_RQST_LINK_DCD AS SRV_RQST_LINK_DCD /* 서비스의뢰연계구분코드*/ , T1.SRV_RQST_APLY_DCD AS SRV_RQST_APLY_DCD /* 서비스의뢰신청구분코드*/ , T1.SRV_RQST_APLY_TCD AS SRV_RQST_APLY_TCD /* 서비스의뢰신청유형코드*/ , T1.SRV_CNSRQ_ID AS SRV_CNSRQ_ID /* 서비스상담의뢰ID*/ , T1.RQST_INST_TYP_DTL_CD AS RQST_INST_TYP_DTL_CD /* 의뢰기관유형상세코드*/ , T1.RQST_INST_TYP_DTL_NM AS RQST_INST_TYP_DTL_NM /* 의뢰기관유형상세명*/ , T1.RQST_SRV_INST_ID AS RQST_SRV_INST_ID /* 의뢰서비스기관ID*/ , (SELECT X.UNT_TASKWK_SE_CD FROM SAA000 X WHERE X.INST_NO = T1.RQST_PRCS_SRV_INST_ID) AS UNT_TASKWK_SE_CD /* 의뢰서비스기관*/ , T1.RQST_SRV_INST_NM AS RQST_SRV_INST_NM /* 의뢰서비스기관명*/ , T1.DSCSN_YMD AS DSCSN_YMD /* 상담일자*/ , T1.RQST_YMD AS RQST_YMD /* 의뢰일자*/ , T1.RQST_INST_PIC_FLNM AS RQST_INST_PIC_FLNM /* 의뢰기관담당자성명*/ , T1.RQST_INST_PIC_TELNO AS RQST_INST_PIC_TELNO /* 의뢰기관담당자전화번호*/ , T1.RQST_INST_PIC_MPNO AS RQST_INST_PIC_MPNO /* 의뢰기관담당자휴대전화번호*/ , T1.CLNT_DSCSN_OPIN_CN AS CLNT_DSCSN_OPIN_CN /* 의뢰인상담소견내용*/ , T1.RQST_INST_PIC_SPCL_CN AS RQST_INST_PIC_SPCL_CN /* 의뢰기관담당자특화내용*/ , T1.RQST_INST_PIC_NTCE_USE_YN AS RQST_INST_PIC_NTCE_USE_YN /* 의뢰기관담당자알림사용여부*/ , T1.TRPR_FLNM AS TRPR_FLNM /* 대상자성명*/ , T1.TRPR_RRNO AS TRPR_RRNO /* 대상자주민등록번호*/ , T1.TRPR_RRNO_ENCPT AS TRPR_RRNO_ENCPT /* 대상자주민등록번호암호화*/ , T1.TRPR_BRDT AS TRPR_BRDT /* 대상자생년월일*/ , T1.TRPR_RRNO_SEX_CD AS TRPR_RRNO_SEX_CD /* 대상자주민등록번호성별코드*/ , T1.TRPR_MGEMD_DEPT_CD AS TRPR_MGEMD_DEPT_CD /* 대상자관리읍면동부서코드*/ , T1.TRPR_TELNO AS TRPR_TELNO /* 대상자전화번호*/ , T1.TRPR_MPNO AS TRPR_MPNO /* 대상자휴대전화번호*/ , T1.TRPR_RDNM_ZIP AS TRPR_RDNM_ZIP /* 대상자도로명우편번호*/ , T1.TRPR_RDNMADR AS TRPR_RDNMADR /* 대상자도로명주소*/ , T1.TRPR_RDNM_DTLADR AS TRPR_RDNM_DTLADR /* 대상자도로명상세주소*/ , T1.HOPE_SPRT_CD_LST AS HOPE_SPRT_CD_LST /* 희망지원코드목록*/ , T1.HOPE_SPRT_ETC_CN AS HOPE_SPRT_ETC_CN /* 희망지원기타내용*/ , T1.TRPR_PRVC_PVAGR_YN AS TRPR_PRVC_PVAGR_YN /* 대상자개인정보제공동의여부*/ , T1.TRPR_OVL_DSDGR_CD AS TRPR_OVL_DSDGR_CD /* 대상자종합장애정도코드*/ , T1.PRCS_RQST_INST_TYP_DTL_CD AS PRCS_RQST_INST_TYP_DTL_CD /* 처리의뢰기관유형상세코드*/ , T1.RQST_PRCS_SRV_INST_ID AS RQST_PRCS_SRV_INST_ID /* 의뢰처리서비스기관ID*/ , T1.RQST_PRCS_SRV_INST_NM AS RQST_PRCS_SRV_INST_NM /* 의뢰처리서비스기관명*/ , T1.RQST_SRC_INST_RSC_PRVSV_ID AS RQST_SRC_INST_RSC_PRVSV_ID /* 의뢰원천기관자원제공서비스ID*/ , T1.RQST_RSC_PRVSV_NM AS RQST_RSC_PRVSV_NM /* 의뢰자원제공서비스명*/ , T1.RQST_APLY_SRV_BGNG_YMD AS RQST_APLY_SRV_BGNG_YMD /* 의뢰신청서비스시작일자*/ , T1.RQST_APLY_SRV_END_YMD AS RQST_APLY_SRV_END_YMD /* 의뢰신청서비스종료일자*/ , T1.RQST_ATCFL_NM AS RQST_ATCFL_NM /* 의뢰첨부파일명*/ , T1.ESB_TX_ID AS ESB_TX_ID /* 연계트랜젝션아이디*/ , T1.ESB_SEQ AS ESB_SEQ /* 연계시퀸스*/ , T1.ESB_IF_ID AS ESB_IF_ID /* 연계인터페이스ID*/ , T1.SND_CD AS SND_CD /* 송신기관코드*/ , T1.RCV_CD AS RCV_CD /* 수신기관코드*/ , T1.ESB_FILE_NAME AS ESB_FILE_NAME /* 연계파일이름*/ , T1.CREATE_TIME AS CREATE_TIME /* 데이터생성일시*/ , T1.ESB_INIT_TIME AS ESB_INIT_TIME /* 연계시작일시*/ , T1.ESB_COMPLITE_TIME AS ESB_COMPLITE_TIME /* 연계종료일시*/ , T1.ESB_STATUS AS ESB_STATUS /* 연계상태*/ , (SELECT aa.SRV_RQST_PRCS_DCD FROM (SELECT T2.SRV_RQST_PRCS_DCD FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa WHERE rownum = 1) AS CAB110_SRV_RQST_PRCS_DCD , (SELECT aa.ESB_STATUS FROM (SELECT T2.ESB_STATUS FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa) AS CAB110_ESB_STATUS , (SELECT aa.SRV_RQST_PRCS_ID FROM (SELECT T2.SRV_RQST_PRCS_ID FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa WHERE rownum = 1) AS SRV_RQST_PRCS_ID FROM CAB100 T1 LEFT JOIN CAB110 T2 ON T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID LEFT JOIN SAA000 S ON S.INST_NO = T1.RQST_PRCS_SRV_INST_ID WHERE 1 = 1
AND T1.RQST_YMD BETWEEN #{PRNMNT_USE_BGNG_YMD} AND #{PRNMNT_USE_END_YMD}
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/ AND (T2.ESB_STATUS != 'S' AND T2.ESB_STATUS != 'Y' OR T2.ESB_STATUS IS NULL) AND S.UNT_TASKWK_SE_CD IS NOT NULL
AND EXISTS ( SELECT 'X' FROM SAA000 X /* 기관*/ WHERE X.INST_NO = T1.RQST_PRCS_SRV_INST_ID /* 의뢰원천기관자원제공서비스ID*/ AND X.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 의뢰신청유형기관단위업무구분코드*/ UNION ALL SELECT 'X' FROM SDA600 F /* 순수자원제공주체*/ WHERE F.INST_NO = T1.RQST_PRCS_SRV_INST_ID AND F.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} )
